    super::handle_key(&mut app, key(KeyCode::Down)); // off the `type` row
    super::handle_key(&mut app, key(KeyCode::Enter));
    for c in "zed".chars() {
        super::handle_key(&mut app, key(KeyCode::Char(c)));
    }
